"""Two independent users/sessions/registers race to charge the same real ticket."""
import concurrent.futures,hashlib,json,pathlib,re,secrets,subprocess,sys,urllib.parse
sys.path.insert(0,'/workspace/fisitaap-env/tests')
from r3_helpers import request,csrf,sql,PASSWORD
from financial180 import api
def main():
    sql('UPDATE pos_shifts s JOIN fisitaap_r2_devices d ON d.id=s.device_id SET s.status="closed",s.closed_at=NOW(),s.expected_cash=s.opening_cash+(SELECT COALESCE(SUM(p.amount),0) FROM pos_payments p JOIN sales x ON x.id=p.sale_id WHERE x.shift_id=s.id AND p.payment_method="Efectivo"),s.closing_cash=s.opening_cash+(SELECT COALESCE(SUM(p.amount),0) FROM pos_payments p JOIN sales x ON x.id=p.sale_id WHERE x.shift_id=s.id AND p.payment_method="Efectivo"),s.difference_amount=0 WHERE d.name LIKE "RACE BOX %" AND s.status="open"')
    status,body=request('manager','/owner-login')
    if status==200:assert request('manager','/owner-login',{'csrf':re.search(r'name="csrf" value="([a-f0-9]+)"',body)[1],'email':'manager@r2.invalid','password':PASSWORD})[0]==302
    shifts={}
    for actor,uid in [('owner',202),('manager',208)]:
        token=secrets.token_hex(32);h=hashlib.sha256(token.encode()).hexdigest();sql('INSERT INTO fisitaap_r2_devices(tenant_id,branch_id,name,token_hash) VALUES(101,301,?,?)',['RACE BOX '+actor,h]);did=sql('SELECT id FROM fisitaap_r2_devices WHERE token_hash=?',[h])[0]['id'];sql('INSERT INTO fisitaap_registers180(tenant_id,branch_id,name,device_id,user_id) VALUES(101,301,?,?,?)',['RACE REGISTER '+actor,did,uid]);_,html=request(actor,'/admin/turnos');ctx=json.loads(re.search(r'window.FISITAAP180=(\{[^<]+\})</script>',html)[1]);_,proof=api('web-session',{'nonce':ctx['nonce'],'user_id':uid},token);assert request(actor,'/api/native/bind',{'csrf':csrf(actor,'/admin/turnos'),'proof':proof['proof']})[0]==200;key=secrets.token_hex(16);request(actor,'/admin/turnos',{'csrf':csrf(actor,'/admin/turnos'),'action':'open','opening_key':key,'opening_cash':0});shifts[actor]=sql('SELECT id FROM pos_shifts WHERE opening_key=?',[key])[0]['id']
    stock=float(sql('SELECT quantity FROM product_inventory WHERE product_id=501 AND branch_id=301')[0]['quantity']);opening=secrets.token_hex(16);request('owner','/admin/ventas',{'csrf':csrf('owner','/admin/turnos'),'action':'quick','open_key':opening,'start_product':1,'product_id':501,'quantity':1});ticket=sql('SELECT id,revision FROM pos_tickets WHERE open_key=?',[opening])[0];keys={a:secrets.token_hex(16) for a in shifts};tokens={a:csrf(a,'/admin/turnos') for a in shifts}
    def charge(actor):
        payload={'csrf':tokens[actor],'payment_key':keys[actor],'revisions['+str(ticket['id'])+']':ticket['revision'],'split_mode':'all','parts':2,'cash':1130};p=subprocess.run(['docker','exec','-i','fisitaap-r2-web','curl','--noproxy','*','-sS','-b','/tmp/r3-'+actor+'.cookies','--data-binary','@-','-w','\n%{http_code}','http://localhost/admin/cobro?ticket='+str(ticket['id'])],input=urllib.parse.urlencode(payload).encode(),capture_output=True,check=True);body,status=p.stdout.rsplit(b'\n',1);return actor,int(status),body.decode()
    with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool:results=list(pool.map(charge,shifts))
    sales=sql('SELECT id,shift_id,total FROM sales WHERE payment_key IN (?,?)',list(keys.values()));assert len(sales)==1 and sales[0]['total']=='1130.00',sales;assert sales[0]['shift_id'] in shifts.values();assert sql('SELECT status,paid_total FROM pos_tickets WHERE id=?',[ticket['id']])[0]=={'status':'paid','paid_total':'1130.00'};assert float(sql('SELECT quantity FROM product_inventory WHERE product_id=501 AND branch_id=301')[0]['quantity'])==stock-1;assert sorted(s for _,s,_ in results)==[302,409],[(actor,status) for actor,status,_ in results];loser=next(body for _,status,body in results if status==409);assert 'La cuenta cambió' in loser and 'No se registró un segundo cobro' in loser
    assert len(sql('SELECT id FROM pos_payments WHERE ticket_id=?',[ticket['id']]))==1
    for actor,sid in shifts.items():
        cash=1130 if sales[0]['shift_id']==sid else 0;request(actor,'/admin/turnos',{'csrf':csrf(actor,'/admin/turnos'),'action':'close','id':sid,'closing_key':secrets.token_hex(16),'other_cash':cash});row=sql('SELECT status,expected_cash,difference_amount FROM pos_shifts WHERE id=?',[sid])[0];assert row['status']=='closed' and float(row['expected_cash'])==cash and row['difference_amount']=='0.00',row
    checks=['two independent device/user/session registers can open separate online shifts','concurrent different-key charges against one revision create exactly one sale, payment and stock reservation; the other cashier receives a human conflict','both shifts close independently with cash credited only to the register that won the charge']
    pathlib.Path('actualizaciones/1.8.0/QA-DOS-CAJAS.json').write_text(json.dumps({'passed':len(checks),'checks':checks,'environment':'two concurrent real PHP/MariaDB HTTP requests with distinct users/cookies/devices; fake money and no printers'},indent=2)+'\n')
    for x in checks:print('PASS',x,flush=True)
if __name__=='__main__':main()
